const Q = (data) => {
  const labels = OPTION_LABELS[data.id];
  const normalized = labels ? {
    ...data,
    answer: labels[0],
    distractors: data.distractors.map((entry, index) => ({ ...entry, text: labels[index + 1] }))
  } : data;
  return definePremiumChoice({
    gradeBand: '3-5',
    difficulty: 4,
    cognitiveTraits: [...TRAITS, ...(normalized.extraTraits || [])],
    reasoningStepCount: normalized.reasoningStepCount || 3,
    ...normalized
  });
};

